function ChapterQTE:RefreshData()

    if #self._allRelate < self._processCnt then
        self.controller:Close()
        return
    end
    
    local group = self._allRelate[self._processCnt]
    local cnt = #group
    
    KTool.SetActive(self.cell.gameObject, false)
    
    ChapterUtils.ResizeContent(self.objs, cnt, self.cell.gameObject)
    for i = 1, cnt do
        local trans = self.objs:GetChild(i - 1)
        local data = group[i]
        self:RefreshCell(trans, data)
    end
    self._second = 0
end


---RefreshCell
---@param trans UnityEngine.Transform
---@param data ChapterQTEVo
function ChapterQTE:RefreshCell(trans, data)
    --print(table.dump(data.area))
    if self._cachedState == nil then
        self._cachedState = {}
    end
    if not isSet(self._cachedState, data.id) then
        self._cachedState[data.id] = ChapterQTEState.New()
    end
    KTool.SetActive(trans.gameObject, false)
    
    trans.anchoredPosition = data.area.center
    local size = Vector2.New(data.area.width, data.area.height)
    local eventObj = trans:Find("eventArea")
    eventObj.sizeDelta = size
    
    
    
    local dragProxy = UIDragProxy.Create(eventObj.gameObject)
    
    dragProxy.onPointerBeginDrag = function (eventData)
        printInfo("onPointerBeginDrag ")

    end
    
    dragProxy.onPointerEndDrag = function (eventData)
        printInfo("onPointerEndDrag ")

    end
    
    local eventProxy = UIEventProxy.Create(eventObj.gameObject)
    
    eventProxy.onPointerClick = function(eventData)
        printInfo("click ")
    end
end



function ChapterQTE:OnUpdate()
